<script setup>
import { computed,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
const route=useRoute(),router=useRouter(),authStore=useAuthStore(),password=ref(''),passwordConfirmation=ref(''),loading=ref(false),error=ref(''),success=ref(false);const token=computed(()=>typeof route.query.token==='string'?route.query.token:''),email=computed(()=>typeof route.query.email==='string'?route.query.email:''),linkIsComplete=computed(()=>Boolean(token.value&&email.value));const submit=async()=>{error.value='';if(!linkIsComplete.value){error.value='This password reset link is incomplete. Request a new link.';return}if(password.value.length<8){error.value='Your new password must be at least 8 characters.';return}if(password.value!==passwordConfirmation.value){error.value='The two passwords do not match.';return}loading.value=true;try{await authStore.resetPassword({token:token.value,email:email.value,password:password.value,password_confirmation:passwordConfirmation.value});success.value=true;password.value='';passwordConfirmation.value=''}catch(err){error.value=err.message||'We couldn’t reset your password. Request a new link and try again.'}finally{loading.value=false}};const requestAnotherLink=()=>router.replace({name:'forgot-password'}),goToLogin=()=>router.replace({name:'login'})
</script><template><main class="password-page"><section class="password-card"><template v-if="success"><h1>Password changed</h1><p>Your new password is ready. You can log in now.</p><button class="primary" @click="goToLogin">Go to log in</button></template><template v-else-if="!linkIsComplete"><h1>Reset link not valid</h1><p>This password reset link is missing information. Request a fresh link and try again.</p><button class="primary" @click="requestAnotherLink">Request a new link</button></template><template v-else><h1>Choose a new password</h1><p>Resetting password for <strong>{{email}}</strong></p><p v-if="error" class="error">{{error}}</p><form @submit.prevent="submit"><label>New password<input v-model="password" type="password" autocomplete="new-password" minlength="8" required></label><label>Confirm new password<input v-model="passwordConfirmation" type="password" autocomplete="new-password" minlength="8" required></label><button class="primary" :disabled="loading">{{loading?'Changing password...':'Change password'}}</button></form><button class="quiet" @click="requestAnotherLink">Request a new reset link</button></template></section></main></template><style scoped>.password-page{min-height:calc(100vh - var(--app-header-height,92px));padding:clamp(48px,8vw,86px) 20px;display:flex;justify-content:center;align-items:flex-start;background:var(--color-bg)}.password-card{width:min(100%,470px);padding:clamp(24px,4vw,38px);border:1px solid var(--color-border);border-radius:16px;background:var(--color-surface);color:var(--color-text)}h1{text-align:center;font-size:1.65rem}p{text-align:center;color:var(--color-muted);line-height:1.6}strong{color:var(--color-text)}label{display:grid;gap:7px;margin:17px 0;font-size:.82rem;font-weight:650}input{min-height:48px;padding:0 14px;border:1px solid var(--color-border);border-radius:10px;background:var(--color-bg);color:var(--color-text);font:inherit}.primary{width:100%;min-height:48px;border:0;border-radius:999px;background:var(--color-accent);color:#fff;font:inherit;font-weight:750}.quiet{width:100%;margin-top:14px;border:0;background:transparent;color:var(--color-muted);font:inherit}.error{padding:11px;border:1px solid var(--color-border);border-radius:9px;color:#dc5f6d}</style>
